mkdir -p /tmp/tools && cat > /tmp/tools/undef.py <<'EOF'
import ast, builtins, importlib, subprocess, sys
files = subprocess.check_output(['git','ls-files','sphinx/*.py'], cwd='/testbed', text=True).split()
for f in files:
    mod = f[:-3].replace('/', '.').removesuffix('.__init__')
    try:
        m = importlib.import_module(mod)
    except Exception as e:
        print(f, 'IMPORT FAIL', e); continue
    tree = ast.parse(open('/testbed/'+f).read())
    # names bound anywhere locally are ignored; crude: collect all Store names, args, defs, imports
    bound = set()
    for n in ast.walk(tree):
        if isinstance(n, ast.Name) and isinstance(n.ctx, (ast.Store, ast.Del)): bound.add(n.id)
        elif isinstance(n, ast.arg): bound.add(n.arg)
        elif isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)): bound.add(n.name)
        elif isinstance(n, (ast.Import, ast.ImportFrom)):
            for a in n.names: bound.add((a.asname or a.name).split('.')[0])
        elif isinstance(n, ast.ExceptHandler) and n.name: bound.add(n.name)
        elif isinstance(n, ast.MatchAs) and n.name: bound.add(n.name)
    loads = {(n.id, n.lineno) for n in ast.walk(tree) if isinstance(n, ast.Name) and isinstance(n.ctx, ast.Load)}
    seen=set()
    for name, ln in sorted(loads, key=lambda x: x[1]):
        if name in bound or hasattr(m, name) or hasattr(builtins, name) or name in seen: continue
        seen.add(name); print(f'{f}:{ln}: {name}')
EOF
cd /testbed && python /tmp/tools/undef.py 2>&1 | grep -v "__file__\|__name__\|__version__\|__all__"

